class Solution {
    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numberOfArithmeticSlices($nums) {
        $n = count($nums);
        if ($n < 3) return 0;

        // dp[i] will be an associative array mapping difference => count of arithmetic subsequences ending at i with that difference
        $dp = array_fill(0, $n, []);
        $res = 0;

        for ($i = 0; $i < $n; ++$i) {
            $dp[$i] = [];
            for ($j = 0; $j < $i; ++$j) {
                // Use 64-bit int for difference to avoid overflow
                $diff = (int)($nums[$i]) - (int)($nums[$j]);
                // count of subsequences ending at j with difference diff
                $countAtJ = isset($dp[$j][$diff]) ? $dp[$j][$diff] : 0;
                // Update count at i with (countAtJ + 1) new subsequences:
                // +1 is for the new pair (nums[j], nums[i]) that could potentially be extended
                $dp[$i][$diff] = ($dp[$i][$diff] ?? 0) + $countAtJ + 1;
                // We only add those subsequences with length >= 3 to the result, i.e.
                // subsequences extended from j (countAtJ subsequences) contribute to result,
                // the new pair itself (the +1) does not form length >= 3 subsequence
                $res += $countAtJ;
            }
        }

        return $res;
    }
}

